   148	pub(super) fn write_all(
   149	    file: &mut File,
   150	    bytes: &[u8],
   151	    mut before_write: impl FnMut(&File, &[u8]) -> io::Result<usize>,
   152	) -> io::Result<()> {
   153	    let mut offset = 0;
   154	    while offset < bytes.len() {
   155	        let remaining = &bytes[offset..];
   156	        match before_write(file, remaining).and_then(|amount| {
   157	            if amount == 0 {
   158	                return Ok(0);
   159	            }
   160	            if amount > remaining.len() {
   161	                return Err(io::Error::new(
   162	                    io::ErrorKind::InvalidData,
   163	                    "atomic file write hook exceeded its input",
   164	                ));
   165	            }
   166	            use std::io::Write;
   167	            file.write(&remaining[..amount])
   168	        }) {
   169	            Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
   170	            Err(error) => return Err(error),
   171	            Ok(0) => {
   172	                return Err(io::Error::new(
   173	                    io::ErrorKind::WriteZero,
   174	                    "atomic file write returned zero",
   175	                ));
   176	            }
   177	            Ok(amount) if amount > bytes.len() - offset => {
   178	                return Err(io::Error::new(
   179	                    io::ErrorKind::InvalidData,
   180	                    "atomic file write exceeded its input",
   181	                ));
   182	            }
   183	            Ok(amount) => offset += amount,
   184	        }
   185	    }
   186	    Ok(())
   187	}
